import {
  HitboxType,
  HitEvent,
  KillfeedEntry,
  PlayerHitPayload,
  PlayerState,
  Room,
  Team,
  Vector3D,
  WEAPON_CONFIGS,
  WeaponConfig,
} from '../shared/types';
import { RoomManager } from './RoomManager';

export interface HitResult {
  valid: boolean;
  reason?: string;
  hitEvent?: HitEvent;
  isKill?: boolean;
  killfeedEntry?: KillfeedEntry;
  respawnAt?: number;
  matchEnded?: boolean;
  winnerTeam?: Team | null;
}

export class CombatEngine {
  public static readonly RESPAWN_DELAY_MS = 3000; // 3 seconds respawn timer
  public static readonly HEADSHOT_MULTIPLIER = 2.5;
  public static readonly LIMB_MULTIPLIER = 0.8;
  public static readonly ARMOR_ABSORPTION_RATE = 0.65; // Armor absorbs 65% of damage
  public static readonly MAX_RAYCAST_BUFFER = 6.0; // Distance tolerance in units for latency buffer

  private roomManager: RoomManager;

  constructor(roomManager: RoomManager) {
    this.roomManager = roomManager;
  }

  /**
   * Euclidean distance between two 3D vectors
   */
  public getDistance(a: Vector3D, b: Vector3D): number {
    const dx = a.x - b.x;
    const dy = a.y - b.y;
    const dz = a.z - b.z;
    return Math.sqrt(dx * dx + dy * dy + dz * dz);
  }

  /**
   * Authoritative hit validation and damage calculation.
   */
  public processHit(
    room: Room,
    shooterId: string,
    payload: PlayerHitPayload
  ): HitResult {
    const shooter = room.players[shooterId];
    const target = room.players[payload.targetId];

    // 1. Basic validation: players exist and alive
    if (!shooter) {
      return { valid: false, reason: 'Shooter does not exist' };
    }
    if (shooter.isDead) {
      return { valid: false, reason: 'Dead players cannot deal damage' };
    }
    if (!target) {
      return { valid: false, reason: 'Target player not found' };
    }
    if (target.isDead) {
      return { valid: false, reason: 'Target is already dead' };
    }
    if (shooter.id === target.id) {
      return { valid: false, reason: 'Self-inflicted damage rejected' };
    }

    // 2. Friendly fire check
    if (room.mode === 'TDM' && shooter.team === target.team) {
      return { valid: false, reason: 'Friendly fire is disabled in TDM' };
    }

    // 3. Weapon configuration check
    const weaponConfig: WeaponConfig =
      WEAPON_CONFIGS[payload.weaponId] || WEAPON_CONFIGS[shooter.currentWeapon];
    if (!weaponConfig) {
      return { valid: false, reason: 'Unknown weapon configuration' };
    }

    // 4. Raycast distance check (server authoritative distance)
    const shooterToTargetDist = this.getDistance(shooter.position, target.position);
    if (shooterToTargetDist > weaponConfig.range + CombatEngine.MAX_RAYCAST_BUFFER) {
      return {
        valid: false,
        reason: `Target out of range (${shooterToTargetDist.toFixed(1)}m > ${weaponConfig.range}m)`,
      };
    }

    // 5. Server-authoritative hitbox determination & headshot validation
    const hitHeightRel = payload.hitPosition.y - target.position.y;
    let validatedHitbox: HitboxType = payload.hitbox;

    // Check hit height relative to player base:
    // Standing player is ~1.85 units tall
    // Head: 1.35m - 2.05m
    // Body: 0.65m - 1.35m
    // Limbs: 0.0m - 0.65m
    if (hitHeightRel >= 1.3) {
      validatedHitbox = 'head';
    } else if (hitHeightRel < 0.6) {
      validatedHitbox = 'limb';
    } else {
      validatedHitbox = 'body';
    }

    const isHeadshot = validatedHitbox === 'head';

    // 6. Multipliers and damage computation
    let multiplier = 1.0;
    if (isHeadshot) {
      multiplier = weaponConfig.headshotMultiplier || CombatEngine.HEADSHOT_MULTIPLIER;
    } else if (validatedHitbox === 'limb') {
      multiplier = CombatEngine.LIMB_MULTIPLIER;
    }

    const rawDamage = Math.round(weaponConfig.damage * multiplier);

    // 7. Armor deduction & Health damage calculation
    let absorbedDamage = 0;
    let healthDamage = rawDamage;

    if (target.armor > 0) {
      // Armor absorbs 65% of the hit
      const maxAbsorbable = Math.round(rawDamage * CombatEngine.ARMOR_ABSORPTION_RATE);
      absorbedDamage = Math.min(target.armor, maxAbsorbable);
      target.armor = Math.max(0, target.armor - absorbedDamage);
      healthDamage = rawDamage - absorbedDamage;
    }

    target.health = Math.max(0, target.health - healthDamage);
    const isKill = target.health <= 0;

    // Construct HitEvent
    const hitEvent: HitEvent = {
      id: `${Date.now()}_${shooter.id}_${target.id}`,
      shooterId: shooter.id,
      targetId: target.id,
      weaponId: weaponConfig.id,
      hitbox: validatedHitbox,
      damage: rawDamage,
      absorbedDamage,
      healthDamage,
      hitPosition: { ...payload.hitPosition },
      isKill,
      isHeadshot,
      timestamp: Date.now(),
    };

    let killfeedEntry: KillfeedEntry | undefined;
    let respawnAt: number | undefined;
    let matchEnded = false;
    let winnerTeam: Team | null = null;

    // 8. On Kill handling
    if (isKill) {
      target.isDead = true;
      target.health = 0;
      target.armor = 0;
      target.deaths += 1;

      shooter.kills += 1;
      shooter.score += isHeadshot ? 150 : 100;

      // Update TDM team scores
      if (room.mode === 'TDM') {
        if (shooter.team === 'ALPHA') {
          room.matchState.scoreAlpha += 1;
        } else if (shooter.team === 'BRAVO') {
          room.matchState.scoreBravo += 1;
        }
      }

      // Check match end conditions
      if (room.mode === 'TDM') {
        if (room.matchState.scoreAlpha >= room.matchState.targetScore) {
          matchEnded = true;
          winnerTeam = 'ALPHA';
          room.matchState.status = 'ended';
          room.matchState.winnerTeam = 'ALPHA';
        } else if (room.matchState.scoreBravo >= room.matchState.targetScore) {
          matchEnded = true;
          winnerTeam = 'BRAVO';
          room.matchState.status = 'ended';
          room.matchState.winnerTeam = 'BRAVO';
        }
      } else if (room.mode === 'FFA') {
        if (shooter.kills >= room.matchState.targetScore) {
          matchEnded = true;
          winnerTeam = 'FFA';
          room.matchState.status = 'ended';
          room.matchState.winnerTeam = 'FFA';
        }
      }

      // Build killfeed entry
      killfeedEntry = {
        id: `kf_${Date.now()}_${shooter.id}`,
        killerId: shooter.id,
        killerName: shooter.nickname,
        killerTeam: shooter.team,
        victimId: target.id,
        victimName: target.nickname,
        victimTeam: target.team,
        weaponId: weaponConfig.id,
        isHeadshot,
        timestamp: Date.now(),
      };

      // Set 3-second respawn timer
      respawnAt = Date.now() + CombatEngine.RESPAWN_DELAY_MS;
      target.respawnAt = respawnAt;
    }

    return {
      valid: true,
      hitEvent,
      isKill,
      killfeedEntry,
      respawnAt,
      matchEnded,
      winnerTeam,
    };
  }

  /**
   * Respawns a player after the 3-second respawn timer expires.
   */
  public respawnPlayer(
    room: Room,
    playerId: string
  ): {
    playerId: string;
    position: Vector3D;
    rotation: { x: number; y: number; z: number };
    health: number;
    armor: number;
  } | null {
    const player = room.players[playerId];
    if (!player) return null;

    const spawnPoint = this.roomManager.getOptimalSpawnPoint(room, player.team, playerId);
    const yaw = player.team === 'BRAVO' ? Math.PI : 0;

    player.isDead = false;
    player.health = 100;
    player.armor = 100;
    player.position = { ...spawnPoint };
    player.rotation = { x: 0, y: yaw, z: 0 };
    player.velocity = { x: 0, y: 0, z: 0 };
    delete player.respawnAt;

    // Replenish ammo for current weapon
    const weaponConfig = WEAPON_CONFIGS[player.currentWeapon] || WEAPON_CONFIGS['AR-76'];
    player.ammo = {
      current: weaponConfig.maxAmmo,
      reserve: weaponConfig.reserveAmmo,
    };

    return {
      playerId: player.id,
      position: player.position,
      rotation: player.rotation,
      health: player.health,
      armor: player.armor,
    };
  }
}

import { Server } from 'socket.io';
import {
  ClientToServerEvents,
  InterServerEvents,
  PlayerInputPayload,
  Room,
  ServerStateSnapshot,
  ServerToClientEvents,
  SocketData,
} from '../shared/types';
import { CombatEngine } from './CombatEngine';
import { RoomManager } from './RoomManager';

export class GameLoop {
  public static readonly TICK_RATE = 60; // 60Hz tick-rate
  public static readonly TICK_INTERVAL_MS = 1000 / GameLoop.TICK_RATE; // ~16.67ms

  private io: Server<ClientToServerEvents, ServerToClientEvents, InterServerEvents, SocketData>;
  private roomManager: RoomManager;
  private combatEngine: CombatEngine;
  private intervalId: NodeJS.Timeout | null = null;
  private isRunning = false;
  private lastTickTime = Date.now();
  private secondAccumulator = 0;

  constructor(
    io: Server<ClientToServerEvents, ServerToClientEvents, InterServerEvents, SocketData>,
    roomManager: RoomManager,
    combatEngine: CombatEngine
  ) {
    this.io = io;
    this.roomManager = roomManager;
    this.combatEngine = combatEngine;
  }

  public start(): void {
    if (this.isRunning) return;
    this.isRunning = true;
    this.lastTickTime = Date.now();

    // High frequency tick loop
    this.intervalId = setInterval(() => {
      this.tick();
    }, GameLoop.TICK_INTERVAL_MS);

    console.log(`[GameLoop] 60Hz Engine Tick Loop initialized (${GameLoop.TICK_INTERVAL_MS.toFixed(2)}ms per tick)`);
  }

  public stop(): void {
    if (!this.isRunning) return;
    this.isRunning = false;
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
    console.log('[GameLoop] Tick loop stopped.');
  }

  /**
   * Main 60Hz tick step
   */
  private tick(): void {
    const now = Date.now();
    const dtMs = now - this.lastTickTime;
    this.lastTickTime = now;

    // Track 1-second interval for match timer countdown
    this.secondAccumulator += dtMs;
    const shouldTickSecond = this.secondAccumulator >= 1000;
    if (shouldTickSecond) {
      this.secondAccumulator -= 1000;
    }

    const rooms = this.roomManager.getAllRooms();

    for (const room of rooms) {
      const playerList = Object.values(room.players);
      if (playerList.length === 0) continue;

      // 1. Check Match Timer Countdown
      if (shouldTickSecond && room.matchState.status === 'in_progress') {
        room.matchState.timeRemaining = Math.max(0, room.matchState.timeRemaining - 1);

        if (room.matchState.timeRemaining <= 0) {
          this.endMatch(room);
        }
      }

      // 2. Check Respawn Timers
      for (const player of playerList) {
        if (player.isDead && player.respawnAt && now >= player.respawnAt) {
          const respawnData = this.combatEngine.respawnPlayer(room, player.id);
          if (respawnData) {
            this.io.to(room.id).emit('game:playerRespawn', respawnData);
          }
        }
      }

      // 3. Broadcast 60Hz State Snapshot to all players in the room
      const snapshot: ServerStateSnapshot = {
        timestamp: now,
        players: playerList,
        matchState: room.matchState,
      };

      this.io.to(room.id).emit('game:stateUpdate', snapshot);
    }
  }

  /**
   * Process client movement input update (authoritative position & rotation reconciliation)
   */
  public handlePlayerInput(playerId: string, payload: PlayerInputPayload): void {
    const room = this.roomManager.getRoomByPlayerId(playerId);
    if (!room) return;

    const player = room.players[playerId];
    if (!player || player.isDead) return;

    // Update player kinematic and animation states
    player.position = { ...payload.position };
    player.rotation = { ...payload.rotation };
    player.velocity = { ...payload.velocity };
    player.isCrouching = payload.isCrouching;
    player.isSprinting = payload.isSprinting;
    player.isAiming = payload.isAiming;
    player.lastProcessedInput = payload.sequenceNumber;
  }

  /**
   * End match when time or score limit is reached
   */
  private endMatch(room: Room): void {
    room.matchState.status = 'ended';

    let winnerTeam = null;
    if (room.mode === 'TDM') {
      if (room.matchState.scoreAlpha > room.matchState.scoreBravo) {
        winnerTeam = 'ALPHA' as const;
      } else if (room.matchState.scoreBravo > room.matchState.scoreAlpha) {
        winnerTeam = 'BRAVO' as const;
      }
    } else {
      // FFA: winner is player with highest kills
      const players = Object.values(room.players);
      players.sort((a, b) => b.kills - a.kills);
      winnerTeam = 'FFA' as const;
    }

    room.matchState.winnerTeam = winnerTeam;

    this.io.to(room.id).emit('game:matchEnd', {
      winnerTeam,
      scoreAlpha: room.matchState.scoreAlpha,
      scoreBravo: room.matchState.scoreBravo,
    });

    console.log(`[GameLoop] Match ended in room ${room.id}. Winner: ${winnerTeam}`);
  }
}

import http from 'http';
import { Server } from 'socket.io';
import {
  BulletData,
  ClientToServerEvents,
  InterServerEvents,
  ServerToClientEvents,
  SocketData,
  WEAPON_CONFIGS,
} from '../shared/types';
import { CombatEngine } from './CombatEngine';
import { GameLoop } from './GameLoop';
import { RoomManager } from './RoomManager';

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3001;

// 1. Create HTTP server with healthcheck and basic CORS headers
const server = http.createServer((req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  if (req.url === '/health' || req.url === '/') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(
      JSON.stringify({
        status: 'online',
        service: 'Tactical-FPS-Server',
        tickRate: GameLoop.TICK_RATE,
        activeRooms: roomManager.getAllRooms().length,
        timestamp: Date.now(),
      })
    );
    return;
  }

  res.writeHead(404);
  res.end('Not Found');
});

// 2. Initialize Socket.io Server with Port 3000 CORS support
const io = new Server<ClientToServerEvents, ServerToClientEvents, InterServerEvents, SocketData>(
  server,
  {
    cors: {
      origin: [
        'http://localhost:3000',
        'http://127.0.0.1:3000',
        'http://localhost:3001',
        'http://127.0.0.1:3001',
        '*',
      ],
      methods: ['GET', 'POST'],
      credentials: true,
    },
    transports: ['websocket', 'polling'],
  }
);

// 3. Initialize Core Subsystems
const roomManager = new RoomManager();
const combatEngine = new CombatEngine(roomManager);
const gameLoop = new GameLoop(io, roomManager, combatEngine);

// 4. Register Socket Event Handlers
io.on('connection', (socket) => {
  socket.data.playerId = socket.id;

  // Ping / Latency measuring
  socket.on('ping:latency', (payload) => {
    socket.emit('pong:latency', {
      clientTimestamp: payload.timestamp,
      serverTimestamp: Date.now(),
    });

    // Update player ping in room state if room exists
    const room = roomManager.getRoomByPlayerId(socket.id);
    if (room && room.players[socket.id]) {
      const rtt = Date.now() - payload.timestamp;
      room.players[socket.id].ping = Math.max(1, Math.round(rtt / 2));
    }
  });

  // Room Creation
  socket.on('room:create', (payload) => {
    try {
      const { room, player } = roomManager.createRoom(socket.id, payload);
      socket.data.roomId = room.id;
      socket.data.nickname = player.nickname;

      socket.join(room.id);
      socket.emit('room:joined', { room, playerId: socket.id });
      socket.to(room.id).emit('room:playerJoined', { player });

      console.log(
        `[RoomManager] Room created: ${room.id} (${room.mode}) by ${player.nickname} (${socket.id})`
      );
    } catch (err: any) {
      socket.emit('room:error', { message: err.message || 'Failed to create room' });
    }
  });

  // Room Join by Code
  socket.on('room:join', (payload) => {
    try {
      const result = roomManager.joinRoom(payload.roomCode, socket.id, payload);
      if (!result.success || !result.room || !result.player) {
        socket.emit('room:error', { message: result.error || 'Failed to join room' });
        return;
      }

      socket.data.roomId = result.room.id;
      socket.data.nickname = result.player.nickname;

      socket.join(result.room.id);
      socket.emit('room:joined', { room: result.room, playerId: socket.id });
      socket.to(result.room.id).emit('room:playerJoined', { player: result.player });

      console.log(
        `[RoomManager] Player ${result.player.nickname} joined room: ${result.room.id} on team ${result.player.team}`
      );
    } catch (err: any) {
      socket.emit('room:error', { message: err.message || 'Error joining room' });
    }
  });

  // Quick Matchmaking
  socket.on('room:quickMatch', (payload) => {
    try {
      const { room, player, isNewRoom } = roomManager.quickMatch(socket.id, payload);
      socket.data.roomId = room.id;
      socket.data.nickname = player.nickname;

      socket.join(room.id);
      socket.emit('room:joined', { room, playerId: socket.id });

      if (isNewRoom) {
        console.log(`[QuickMatch] Created new room ${room.id} for ${player.nickname}`);
      } else {
        socket.to(room.id).emit('room:playerJoined', { player });
        console.log(`[QuickMatch] Matched ${player.nickname} into existing room ${room.id}`);
      }
    } catch (err: any) {
      socket.emit('room:error', { message: err.message || 'Quick match failed' });
    }
  });

  // Explicit Leave Room
  socket.on('room:leave', () => {
    handlePlayerLeave(socket.id);
  });

  // Player Movement & Input Update
  socket.on('player:input', (payload) => {
    gameLoop.handlePlayerInput(socket.id, payload);
  });

  // Player Fire Weapon
  socket.on('player:fire', (payload) => {
    const room = roomManager.getRoomByPlayerId(socket.id);
    if (!room) return;

    const player = room.players[socket.id];
    if (!player || player.isDead) return;

    const weapon = WEAPON_CONFIGS[payload.weaponId] || WEAPON_CONFIGS[player.currentWeapon];
    if (!weapon) return;

    // Melee weapons have 0 maxAmmo and infinite swings
    if (weapon.category !== 'melee') {
      if (player.ammo.current <= 0) {
        return; // Empty magazine
      }
      player.ammo.current = Math.max(0, player.ammo.current - 1);
    }

    const bullet: BulletData = {
      id: `b_${Date.now()}_${socket.id}_${Math.random().toString(36).substring(2, 7)}`,
      shooterId: socket.id,
      weaponId: weapon.id,
      origin: payload.origin,
      direction: payload.direction,
      timestamp: payload.timestamp || Date.now(),
      speed: weapon.bulletSpeed,
    };

    // Broadcast projectile fire to other clients in the room for visual tracers and audio
    socket.to(room.id).emit('game:playerFired', bullet);
  });

  // Player Reload Weapon
  socket.on('player:reload', () => {
    const room = roomManager.getRoomByPlayerId(socket.id);
    if (!room) return;

    const player = room.players[socket.id];
    if (!player || player.isDead) return;

    const weapon = WEAPON_CONFIGS[player.currentWeapon];
    if (!weapon || weapon.category === 'melee') return;

    const needed = weapon.maxAmmo - player.ammo.current;
    if (needed <= 0 || player.ammo.reserve <= 0) return;

    const reloadAmount = Math.min(needed, player.ammo.reserve);
    player.ammo.current += reloadAmount;
    player.ammo.reserve -= reloadAmount;
  });

  // Switch Weapon
  socket.on('player:switchWeapon', ({ weaponId }) => {
    const room = roomManager.getRoomByPlayerId(socket.id);
    if (!room) return;

    const player = room.players[socket.id];
    if (!player || player.isDead) return;

    const weapon = WEAPON_CONFIGS[weaponId];
    if (!weapon) return;

    player.currentWeapon = weaponId;
    player.ammo = {
      current: weapon.maxAmmo,
      reserve: weapon.reserveAmmo,
    };
  });

  // Server-Authoritative Hit Validation
  socket.on('player:hit', (payload) => {
    const room = roomManager.getRoomByPlayerId(socket.id);
    if (!room) return;

    const hitResult = combatEngine.processHit(room, socket.id, payload);
    if (!hitResult.valid || !hitResult.hitEvent) {
      return;
    }

    // Broadcast hit event to all players in the room for hitmarkers, health bar updates, and audio
    io.to(room.id).emit('game:playerHit', hitResult.hitEvent);

    // If hit resulted in elimination
    if (hitResult.isKill && hitResult.killfeedEntry) {
      io.to(room.id).emit('game:killfeed', hitResult.killfeedEntry);
      io.to(room.id).emit('game:playerDied', {
        victimId: hitResult.hitEvent.targetId,
        killerId: hitResult.hitEvent.shooterId,
        killfeed: hitResult.killfeedEntry,
        respawnAt: hitResult.respawnAt || Date.now() + 3000,
      });

      // If match victory was reached
      if (hitResult.matchEnded) {
        io.to(room.id).emit('game:matchEnd', {
          winnerTeam: hitResult.winnerTeam || null,
          scoreAlpha: room.matchState.scoreAlpha,
          scoreBravo: room.matchState.scoreBravo,
        });
      }
    }
  });

  // Disconnection handler
  socket.on('disconnect', () => {
    handlePlayerLeave(socket.id);
  });
});

/**
 * Handle room leave cleanup
 */
function handlePlayerLeave(playerId: string) {
  const result = roomManager.leaveRoom(playerId);
  if (result.roomCode && !result.roomDestroyed) {
    io.to(result.roomCode).emit('room:playerLeft', {
      playerId,
      newHostId: result.newHostId,
    });
    console.log(
      `[RoomManager] Player ${playerId} left room ${result.roomCode}. Host migrated to: ${result.newHostId}`
    );
  }
}

// 5. Start the Server and the 60Hz Game Loop
server.listen(PORT, () => {
  console.log(`=======================================================`);
  console.log(`🚀 Tactical FPS Multiplayer Server running on port ${PORT}`);
  console.log(`🌐 CORS enabled for http://localhost:3000`);
  console.log(`⚡ 60Hz Server-Authoritative Physics & Combat Active`);
  console.log(`=======================================================`);
  gameLoop.start();
});

// Process signal handling for clean teardown
process.on('SIGINT', () => {
  console.log('Shutting down server...');
  gameLoop.stop();
  server.close(() => {
    process.exit(0);
  });
});

process.on('SIGTERM', () => {
  console.log('Terminating server...');
  gameLoop.stop();
  server.close(() => {
    process.exit(0);
  });
});

import {
  GameMode,
  MatchState,
  PlayerState,
  Room,
  Team,
  Vector3D,
  WEAPON_CONFIGS,
  WeaponId,
} from '../shared/types';

export const SPAWN_POINTS: Record<Team, Vector3D[]> = {
  ALPHA: [
    { x: -28, y: 1.0, z: -20 },
    { x: -25, y: 1.0, z: -24 },
    { x: -20, y: 1.0, z: -18 },
