  rotation: { x: number; y: number; z: number }; // Pitch (x), Yaw (y), Roll (z)
  velocity: Vector3D;
  isCrouching: boolean;
  isSprinting: boolean;
  isAiming: boolean;
  isReloading: boolean;
  isFiring: boolean;
  isDead: boolean;
  health: number; // 0 - 100
  armor: number; // 0 - 100
  currentWeapon: WeaponId;
  ammo: {
    current: number;
    reserve: number;
  };
  score: number;
  kills: number;
  deaths: number;
  assists: number;
  ping: number;
  lastProcessedInput?: number;
  respawnAt?: number; // Epoch timestamp when player will respawn
}

export interface BulletData {
  id: string;
  shooterId: string;
  weaponId: WeaponId;
  origin: Vector3D;
  direction: Vector3D;
  timestamp: number;
  speed: number;
}

export type HitboxType = 'head' | 'body' | 'limb';

export interface HitEvent {
  id: string;
  shooterId: string;
  targetId: string;
  weaponId: WeaponId;
  hitbox: HitboxType;
  damage: number;
  absorbedDamage: number;
  healthDamage: number;
  hitPosition: Vector3D;
  isKill: boolean;
  isHeadshot: boolean;
  timestamp: number;
}

export interface KillfeedEntry {
  id: string;
  killerId: string;
  killerName: string;
  killerTeam: Team;
  victimId: string;
  victimName: string;
  victimTeam: Team;
  weaponId: WeaponId;
  isHeadshot: boolean;
  timestamp: number;
}

export type MatchStatus = 'waiting' | 'in_progress' | 'ended';

export interface MatchState {
  status: MatchStatus;
  timeRemaining: number; // In seconds
  totalMatchTime: number; // Default 600s (10 min)
  scoreAlpha: number;
  scoreBravo: number;
  targetScore: number; // e.g. 50 in TDM, 30 in FFA
  winnerTeam: Team | null;
}

export interface Room {
  id: string; // 6-digit alphanumeric code e.g. "X7K9M2"
  name: string;
  hostId: string;
  mode: GameMode;
  maxPlayers: number;
  players: Record<string, PlayerState>;
  matchState: MatchState;
  createdAt: number;
}

// ----------------------------------------------------------------------------
// Client-Server Protocol Interfaces
// ----------------------------------------------------------------------------

export interface PlayerInputPayload {
  position: Vector3D;
  rotation: { x: number; y: number; z: number };
  velocity: Vector3D;
  isCrouching: boolean;
  isSprinting: boolean;
  isAiming: boolean;
  sequenceNumber: number;
  timestamp: number;
}

export interface PlayerFirePayload {
  weaponId: WeaponId;
  origin: Vector3D;
  direction: Vector3D;
  timestamp: number;
}

export interface PlayerHitPayload {
  targetId: string;
  weaponId: WeaponId;
  hitbox: HitboxType;
  hitPosition: Vector3D;
  clientTimestamp: number;
}

export interface CreateRoomPayload {
  nickname: string;
  roomName?: string;
  mode: GameMode;
  team?: Team;
  maxPlayers?: number;
}

export interface JoinRoomPayload {
  roomCode: string;
  nickname: string;
  preferredTeam?: Team;
}

export interface QuickMatchPayload {
  nickname: string;
  preferredMode?: GameMode;
}

export interface ServerStateSnapshot {
  timestamp: number;
  players: PlayerState[];
  matchState: MatchState;
}

// Socket.io Event Definitions
export interface ServerToClientEvents {
  'room:joined': (data: { room: Room; playerId: string }) => void;
  'room:error': (data: { message: string }) => void;
  'room:playerJoined': (data: { player: PlayerState }) => void;
  'room:playerLeft': (data: { playerId: string; newHostId?: string }) => void;
  'game:stateUpdate': (snapshot: ServerStateSnapshot) => void;
  'game:playerFired': (bullet: BulletData) => void;
  'game:playerHit': (hit: HitEvent) => void;
  'game:playerDied': (data: {
    victimId: string;
    killerId: string;
    killfeed: KillfeedEntry;
    respawnAt: number;
  }) => void;
  'game:playerRespawn': (data: {
    playerId: string;
    position: Vector3D;
    rotation: { x: number; y: number; z: number };
    health: number;
    armor: number;
  }) => void;
  'game:killfeed': (entry: KillfeedEntry) => void;
  'game:matchEnd': (data: {
    winnerTeam: Team | null;
    scoreAlpha: number;
    scoreBravo: number;
  }) => void;
  'pong:latency': (data: { clientTimestamp: number; serverTimestamp: number }) => void;
}

export interface ClientToServerEvents {
  'room:create': (payload: CreateRoomPayload) => void;
  'room:join': (payload: JoinRoomPayload) => void;
  'room:quickMatch': (payload: QuickMatchPayload) => void;
  'room:leave': () => void;
  'player:input': (payload: PlayerInputPayload) => void;
  'player:fire': (payload: PlayerFirePayload) => void;
  'player:hit': (payload: PlayerHitPayload) => void;
  'player:reload': () => void;
  'player:switchWeapon': (data: { weaponId: WeaponId }) => void;
  'ping:latency': (data: { timestamp: number }) => void;
}

export interface InterServerEvents {
  ping: () => void;
}

export interface SocketData {
  playerId: string;
  roomId?: string;
  nickname?: string;
}

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --background: #07090e;
  --foreground: #f3f4f6;
  --font-mono: 'JetBrains Mono', monospace;
}

* {
  box-sizing: border-box;
}

body {
  color: var(--foreground);
  background: var(--background);
  font-family: var(--font-mono), system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
  margin: 0;
  padding: 0;
  width: 100vw;
  height: 100vh;
}

/* Custom Tactical Scrollbars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: #0b0f17;
}

::-webkit-scrollbar-thumb {
  background: #1f293d;
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: #00f0ff88;
}

/* Tactical clipped corners */
.clip-tactical {
  clip-path: polygon(
    10px 0%,
    calc(100% - 10px) 0%,
    100% 10px,
    100% calc(100% - 10px),
    calc(100% - 10px) 100%,
    10px 100%,
    0% calc(100% - 10px),
    0% 10px
  );
}

.clip-angle-br {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
}

.clip-angle-tl {
  clip-path: polygon(14px 0, 100% 0, 100% 100%, 0 100%, 0 14px);
}

/* Glow Utilities */
.glow-cyan {
  box-shadow: 0 0 20px rgba(0, 240, 255, 0.35);
}

.glow-red {
  box-shadow: 0 0 20px rgba(255, 70, 85, 0.35);
}

.glow-gold {
  box-shadow: 0 0 20px rgba(234, 179, 8, 0.35);
}

/* Subtle scanlines effect */
.scanlines {
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%,
    rgba(0, 0, 0, 0.25) 50%
  ), linear-gradient(
    90deg,
    rgba(255, 0, 0, 0.03),
    rgba(0, 255, 0, 0.01),
    rgba(0, 0, 255, 0.03)
  );
  background-size: 100% 3px, 6px 100%;
}

