'use client';

import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { getHazardTexture } from './textures';
import { JumpPadConfig } from './collision';

interface JumpPadProps {
  config: JumpPadConfig;
  onLaunch?: () => void;
}

export const JumpPad: React.FC<JumpPadProps> = ({ config }) => {
  const groupRef = useRef<THREE.Group>(null);
  const ringRef1 = useRef<THREE.Mesh>(null);
  const ringRef2 = useRef<THREE.Mesh>(null);
  const beamRef = useRef<THREE.Mesh>(null);
  const coreLightRef = useRef<THREE.PointLight>(null);

  const hazardTexture = useMemo(() => {
    const tex = getHazardTexture().clone();
    tex.repeat.set(4, 1);
    tex.needsUpdate = true;
    return tex;
  }, []);

  useFrame((state, delta) => {
    const time = state.clock.getElapsedTime();

    // Pulse core light intensity
    if (coreLightRef.current) {
      coreLightRef.current.intensity = 2.5 + Math.sin(time * 6) * 1.0;
    }

    // Rotate and animate floating energy rings
    if (ringRef1.current) {
      ringRef1.current.rotation.y += delta * 1.8;
      ringRef1.current.position.y = 0.25 + Math.sin(time * 3) * 0.08;
    }

    if (ringRef2.current) {
      ringRef2.current.rotation.y -= delta * 2.4;
      ringRef2.current.position.y = 0.45 + Math.cos(time * 3.5) * 0.1;
      const scale = 0.9 + Math.sin(time * 4) * 0.1;
      ringRef2.current.scale.set(scale, scale, 1);
    }

    // Energy vertical beam column oscillation
    if (beamRef.current) {
      const mat = beamRef.current.material as THREE.MeshBasicMaterial;
      if (mat) {
        mat.opacity = 0.35 + Math.sin(time * 8) * 0.15;
      }
      beamRef.current.rotation.y += delta * 0.8;
    }
  });

  return (
    <group ref={groupRef} position={config.position}>
      {/* 1. Heavy Industrial Octagonal Base Plate */}
      <mesh position={[0, 0.04, 0]} receiveShadow>
        <cylinderGeometry args={[config.radius, config.radius * 1.08, 0.08, 8]} />
        <meshStandardMaterial color="#0f172a" roughness={0.6} metalness={0.8} />
      </mesh>

      {/* 2. Hazard Caution Rim Ring */}
      <mesh position={[0, 0.085, 0]} rotation={[-Math.PI / 2, 0, 0]} receiveShadow>
        <ringGeometry args={[config.radius * 0.72, config.radius * 0.98, 32]} />
        <meshStandardMaterial
          map={hazardTexture}
          roughness={0.4}
          metalness={0.3}
          side={THREE.DoubleSide}
        />
      </mesh>

      {/* 3. Outer Emissive Neon Blue Guide Ring */}
      <mesh position={[0, 0.09, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[config.radius * 0.65, config.radius * 0.71, 32]} />
        <meshBasicMaterial color="#06b6d4" />
      </mesh>

      {/* 4. Sunken Energy Induction Chamber */}
      <mesh position={[0, 0.05, 0]}>
        <cylinderGeometry args={[config.radius * 0.62, config.radius * 0.62, 0.06, 24]} />
        <meshStandardMaterial color="#050811" roughness={0.9} />
      </mesh>

      {/* 5. Center High-Output Grav-Emitter Dome */}
      <mesh position={[0, 0.09, 0]}>
        <sphereGeometry args={[config.radius * 0.28, 16, 16, 0, Math.PI * 2, 0, Math.PI / 2]} />
        <meshStandardMaterial
          color="#0891b2"
          emissive="#06b6d4"
          emissiveIntensity={1.8}
          roughness={0.2}
          metalness={0.9}
        />
      </mesh>

      {/* 6. Floating Holographic Energy Rings */}
      <mesh ref={ringRef1} rotation={[-Math.PI / 2, 0, 0]}>
        <torusGeometry args={[config.radius * 0.45, 0.02, 12, 32]} />
        <meshBasicMaterial color="#22d3ee" transparent opacity={0.85} />
      </mesh>

      <mesh ref={ringRef2} rotation={[-Math.PI / 2, 0, 0]}>
        <torusGeometry args={[config.radius * 0.32, 0.015, 12, 32]} />
        <meshBasicMaterial color="#67e8f9" transparent opacity={0.7} />
      </mesh>

      {/* 7. Vertical Grav-Lift Energy Beam Cylinder */}
      <mesh ref={beamRef} position={[0, 1.2, 0]}>
        <cylinderGeometry args={[config.radius * 0.38, config.radius * 0.48, 2.4, 16, 1, true]} />
        <meshBasicMaterial
          color="#06b6d4"
          transparent
          opacity={0.35}
          side={THREE.DoubleSide}
          blending={THREE.AdditiveBlending}
          depthWrite={false}
        />
      </mesh>

      {/* 8. Jump Pad Local Point Light */}
      <pointLight
        ref={coreLightRef}
        color="#06b6d4"
        intensity={3.0}
        distance={7}
        decay={2}
        position={[0, 0.6, 0]}
      />
    </group>
  );
};

'use client';

import * as THREE from 'three';

// Cache generated textures so they are created once
let cachedGridTexture: THREE.CanvasTexture | null = null;
let cachedHazardTexture: THREE.CanvasTexture | null = null;
let cachedMetalTexture: THREE.CanvasTexture | null = null;
let cachedConcreteTexture: THREE.CanvasTexture | null = null;
let cachedHexTexture: THREE.CanvasTexture | null = null;
let cachedDecalTexture: THREE.CanvasTexture | null = null;

export function getGridTexture(): THREE.CanvasTexture {
  if (cachedGridTexture) return cachedGridTexture;
  if (typeof document === 'undefined') return new THREE.CanvasTexture({} as any);

  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');

  if (ctx) {
    // Base dark industrial slate
    ctx.fillStyle = '#11151f';
    ctx.fillRect(0, 0, 512, 512);

    // Grid panels
    const tileSize = 64;
    for (let x = 0; x < 512; x += tileSize) {
      for (let y = 0; y < 512; y += tileSize) {
        // Inner tile fill
        ctx.fillStyle = (x / tileSize + y / tileSize) % 2 === 0 ? '#141a27' : '#121722';
        ctx.fillRect(x + 2, y + 2, tileSize - 4, tileSize - 4);

        // Border groove
        ctx.strokeStyle = '#0b0e16';
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 1, y + 1, tileSize - 2, tileSize - 2);

        // Highlight seam
        ctx.strokeStyle = '#222d42';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(x + 3, y + tileSize - 3);
        ctx.lineTo(x + tileSize - 3, y + tileSize - 3);
        ctx.lineTo(x + tileSize - 3, y + 3);
        ctx.stroke();

        // Corner rivets
        ctx.fillStyle = '#334155';
        ctx.fillRect(x + 6, y + 6, 2, 2);
        ctx.fillRect(x + tileSize - 8, y + 6, 2, 2);
        ctx.fillRect(x + 6, y + tileSize - 8, 2, 2);
        ctx.fillRect(x + tileSize - 8, y + tileSize - 8, 2, 2);
      }
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearMipmapLinearFilter;
  cachedGridTexture = texture;
  return texture;
}

export function getHazardTexture(): THREE.CanvasTexture {
  if (cachedHazardTexture) return cachedHazardTexture;
  if (typeof document === 'undefined') return new THREE.CanvasTexture({} as any);

  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');

  if (ctx) {
    // Safety orange / amber and carbon black stripes
    ctx.fillStyle = '#d97706'; // Intense amber
    ctx.fillRect(0, 0, 256, 256);

    ctx.fillStyle = '#131418'; // Dark charcoal
    ctx.beginPath();
    const stripeWidth = 32;
    for (let i = -256; i < 512; i += stripeWidth * 2) {
      ctx.moveTo(i, 0);
      ctx.lineTo(i + stripeWidth, 0);
      ctx.lineTo(i + stripeWidth + 256, 256);
      ctx.lineTo(i + 256, 256);
      ctx.closePath();
    }
    ctx.fill();

    // Weathering scratches
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    for (let j = 0; j < 40; j++) {
      const rx = Math.random() * 256;
      const ry = Math.random() * 256;
      ctx.fillRect(rx, ry, Math.random() * 20 + 5, 1);
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  cachedHazardTexture = texture;
  return texture;
}

export function getMetalPlateTexture(): THREE.CanvasTexture {
  if (cachedMetalTexture) return cachedMetalTexture;
  if (typeof document === 'undefined') return new THREE.CanvasTexture({} as any);

  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');

  if (ctx) {
    // Dark gunmetal base
    ctx.fillStyle = '#181e2b';
    ctx.fillRect(0, 0, 512, 512);

    // Large reinforced armor slabs
    const slabW = 256;
    const slabH = 128;
    for (let y = 0; y < 512; y += slabH) {
      for (let x = 0; x < 512; x += slabW) {
        ctx.fillStyle = (x + y) % (slabW * 2) === 0 ? '#1b2230' : '#161c28';
        ctx.fillRect(x + 3, y + 3, slabW - 6, slabH - 6);

        // Seam shadow
        ctx.strokeStyle = '#0d111a';
        ctx.lineWidth = 3;
        ctx.strokeRect(x + 1, y + 1, slabW - 2, slabH - 2);

        // Emissive-like specular chamfer
        ctx.strokeStyle = '#2d3b55';
        ctx.lineWidth = 1;
        ctx.strokeRect(x + 4, y + 4, slabW - 8, slabH - 8);

        // Heavy bolts
        ctx.fillStyle = '#475569';
        [x + 12, x + slabW - 12].forEach((bx) => {
          [y + 12, y + slabH - 12].forEach((by) => {
            ctx.beginPath();
            ctx.arc(bx, by, 3, 0, Math.PI * 2);
            ctx.fill();
          });
        });
      }
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  cachedMetalTexture = texture;
  return texture;
}

export function getConcreteTexture(): THREE.CanvasTexture {
  if (cachedConcreteTexture) return cachedConcreteTexture;
  if (typeof document === 'undefined') return new THREE.CanvasTexture({} as any);

  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');

  if (ctx) {
    // Brutalist concrete raw tone
    ctx.fillStyle = '#1e2430';
    ctx.fillRect(0, 0, 512, 512);

    // Speckle noise
    for (let i = 0; i < 4000; i++) {
      const x = Math.random() * 512;
      const y = Math.random() * 512;
      const gray = Math.floor(Math.random() * 30 + 20);
      ctx.fillStyle = `rgb(${gray}, ${gray + 3}, ${gray + 8})`;
      ctx.fillRect(x, y, 1.5, 1.5);
    }

    // Concrete formwork tie holes
    ctx.fillStyle = '#0f131a';
    for (let y = 64; y < 512; y += 128) {
      for (let x = 64; x < 512; x += 128) {
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = '#2a3445';
        ctx.lineWidth = 1;
        ctx.stroke();
      }
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  cachedConcreteTexture = texture;
  return texture;
}

export function getHexGridTexture(): THREE.CanvasTexture {
  if (cachedHexTexture) return cachedHexTexture;
  if (typeof document === 'undefined') return new THREE.CanvasTexture({} as any);

  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');

  if (ctx) {
    ctx.fillStyle = '#081018';
    ctx.fillRect(0, 0, 256, 256);

    ctx.strokeStyle = 'rgba(6, 182, 212, 0.45)';
    ctx.lineWidth = 1.5;

    const hexR = 24;
    const h = hexR * Math.sqrt(3);
    for (let y = 0; y < 256 + h; y += h) {
      for (let x = 0; x < 256 + hexR * 3; x += hexR * 3) {
        drawHex(ctx, x, y, hexR);
        drawHex(ctx, x + hexR * 1.5, y + h / 2, hexR);
      }
    }
  }

  function drawHex(c: CanvasRenderingContext2D, cx: number, cy: number, r: number) {
    c.beginPath();
    for (let i = 0; i < 6; i++) {
      const angle = (Math.PI / 3) * i;
      const hx = cx + r * Math.cos(angle);
      const hy = cy + r * Math.sin(angle);
      if (i === 0) c.moveTo(hx, hy);
      else c.lineTo(hx, hy);
    }
    c.closePath();
    c.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  cachedHexTexture = texture;
  return texture;
}

export function getDecalTexture(label: string = 'OUTPOST-09'): THREE.CanvasTexture {
  if (cachedDecalTexture) return cachedDecalTexture;
  if (typeof document === 'undefined') return new THREE.CanvasTexture({} as any);

  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 256;
  const ctx = canvas.getContext('2d');

  if (ctx) {
    ctx.fillStyle = '#111722';
    ctx.fillRect(0, 0, 512, 256);

    // Accent line
    ctx.fillStyle = '#06b6d4';
    ctx.fillRect(20, 20, 8, 216);

    // Military stencil header
    ctx.fillStyle = '#f8fafc';
    ctx.font = '900 48px monospace';
    ctx.fillText(label, 40, 75);

    // Subtext
    ctx.fillStyle = '#94a3b8';
    ctx.font = '600 20px monospace';
    ctx.fillText('TACTICAL SECTOR // RESTRICTED ACCESS', 40, 115);
    ctx.fillText('GRID REF: 52.88.941 // DEFCON 1', 40, 145);

    // Barcode design
    ctx.fillStyle = '#38bdf8';
    for (let x = 40; x < 400; x += Math.random() * 8 + 4) {
      ctx.fillRect(x, 175, Math.random() * 4 + 2, 45);
    }
  }

  const texture = new THREE.CanvasTexture(canvas);
  cachedDecalTexture = texture;
  return texture;
}

'use client';

import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { PlayerState, Team, WeaponId } from '@/types/game';
import { WeaponModel } from '../weapons/WeaponModel';

interface ThirdPersonPlayerProps {
  player: PlayerState;
}

export const ThirdPersonPlayer: React.FC<ThirdPersonPlayerProps> = ({ player }) => {
  const rootGroupRef = useRef<THREE.Group>(null);
  const torsoGroupRef = useRef<THREE.Group>(null);
  const leftLegRef = useRef<THREE.Group>(null);
  const rightLegRef = useRef<THREE.Group>(null);
  const leftArmRef = useRef<THREE.Group>(null);
  const rightArmRef = useRef<THREE.Group>(null);
  const headGroupRef = useRef<THREE.Group>(null);
  const muzzleFlashRef = useRef<THREE.PointLight>(null);
  const billboardRef = useRef<THREE.Group>(null);

  // Target positions & rotations for netcode interpolation
  const targetPos = useRef<THREE.Vector3>(
    new THREE.Vector3(player.position.x, player.position.y, player.position.z)
  );
  const currentPos = useRef<THREE.Vector3>(
    new THREE.Vector3(player.position.x, player.position.y, player.position.z)
  );

  const targetYaw = useRef<number>(player.rotation.y || 0);
  const currentYaw = useRef<number>(player.rotation.y || 0);
  const targetPitch = useRef<number>(player.rotation.x || 0);
  const currentPitch = useRef<number>(player.rotation.x || 0);

  const walkCycleRef = useRef<number>(0);

  // Update target coordinates whenever player prop updates
  targetPos.current.set(player.position.x, player.position.y, player.position.z);
  targetYaw.current = player.rotation.y || 0;
  targetPitch.current = player.rotation.x || 0;

  // Determine team color accents
  const teamColors = useMemo(() => {
    switch (player.team) {
      case 'ALPHA':
        return {
          primary: '#0284c7', // Ocean Blue
          accent: '#06b6d4', // Cyan
          emissive: '#22d3ee', // Bright Cyan Glow
          armor: '#1e293b', // Slate Charcoal
          visor: '#00f0ff',
        };
      case 'BRAVO':
        return {
          primary: '#dc2626', // Crimson Red
          accent: '#ea580c', // Orange
          emissive: '#f97316', // Bright Amber Glow
          armor: '#18181b', // Carbon Black
          visor: '#ff3344',
        };
      case 'FFA':
      default:
        return {
          primary: '#d97706', // Gold Amber
          accent: '#eab308', // Yellow
          emissive: '#fde047', // Yellow Glow
          armor: '#1e1e24', // Dystopian Gray
          visor: '#fbbf24',
        };
    }
  }, [player.team]);

  // Netcode Interpolation & Animation Frame Loop
  useFrame((state, delta) => {
    if (!rootGroupRef.current) return;

    // Smoothly lerp position & rotation from network ticks
    currentPos.current.lerp(targetPos.current, THREE.MathUtils.clamp(delta * 18, 0, 1));
    currentYaw.current = THREE.MathUtils.lerp(
      currentYaw.current,
      targetYaw.current,
      THREE.MathUtils.clamp(delta * 18, 0, 1)
    );
    currentPitch.current = THREE.MathUtils.lerp(
      currentPitch.current,
      targetPitch.current,
      THREE.MathUtils.clamp(delta * 18, 0, 1)
    );

    // Apply root position
    rootGroupRef.current.position.copy(currentPos.current);
    rootGroupRef.current.rotation.y = currentYaw.current;

    // Pitch head & upper arms with view pitch
    if (headGroupRef.current) {
      headGroupRef.current.rotation.x = currentPitch.current * 0.8;
    }
    if (rightArmRef.current) {
      rightArmRef.current.rotation.x = -Math.PI / 2.3 + currentPitch.current * 0.7;
    }
    if (leftArmRef.current) {
      leftArmRef.current.rotation.x = -Math.PI / 2.5 + currentPitch.current * 0.7;
    }

    // Check if moving (based on velocity or position change)
    const velX = player.velocity?.x || 0;
    const velZ = player.velocity?.z || 0;
    const speed = Math.hypot(velX, velZ);
    const isMoving = speed > 0.3 || currentPos.current.distanceTo(targetPos.current) > 0.05;

    // Procedural leg walking animation
    if (isMoving && !player.isDead) {
      const walkSpeed = player.isSprinting ? 14 : 9;
      walkCycleRef.current += delta * walkSpeed;

      const legAngle = Math.sin(walkCycleRef.current) * (player.isSprinting ? 0.65 : 0.45);
      if (leftLegRef.current) leftLegRef.current.rotation.x = legAngle;
      if (rightLegRef.current) rightLegRef.current.rotation.x = -legAngle;

      // Slight torso bobbing
      if (torsoGroupRef.current) {
        torsoGroupRef.current.position.y =
          (player.isCrouching ? 0.6 : 0.95) + Math.abs(Math.sin(walkCycleRef.current * 2)) * 0.04;
      }
    } else {
      // Idle pose reset
      if (leftLegRef.current) {
        leftLegRef.current.rotation.x = THREE.MathUtils.lerp(
          leftLegRef.current.rotation.x,
          0,
          delta * 10
        );
      }
      if (rightLegRef.current) {
        rightLegRef.current.rotation.x = THREE.MathUtils.lerp(
          rightLegRef.current.rotation.x,
          0,
          delta * 10
        );
      }
      if (torsoGroupRef.current) {
        torsoGroupRef.current.position.y = THREE.MathUtils.lerp(
          torsoGroupRef.current.position.y,
          player.isCrouching ? 0.6 : 0.95,
          delta * 10
        );
      }
    }

    // Muzzle flash visibility when firing
    if (muzzleFlashRef.current) {
      muzzleFlashRef.current.intensity = player.isFiring ? 4.0 : 0.0;
    }

    // Billboard overhead tag always faces the camera
    if (billboardRef.current) {
      billboardRef.current.quaternion.copy(state.camera.quaternion);
    }
  });

  // Calculate health & armor bar percentages
  const healthPercent = Math.max(0, Math.min(1, (player.health ?? 100) / 100));
  const armorPercent = Math.max(0, Math.min(1, (player.armor ?? 0) / 100));

  if (player.isDead) {
    // Render downed / elimination marker or flat ragdoll box
    return (
      <group ref={rootGroupRef} position={[player.position.x, player.position.y, player.position.z]}>
        <mesh position={[0, 0.15, 0]}>
          <boxGeometry args={[0.8, 0.3, 1.6]} />
          <meshStandardMaterial color="#334155" roughness={0.9} />
        </mesh>
      </group>
    );
  }

  return (
    <group ref={rootGroupRef}>
      {/* ================================================================== */}
      {/* 1. FLOATING OVERHEAD BILLBOARD (NAME TAG & HEALTH / ARMOR BARS)    */}
      {/* ================================================================== */}
      <group ref={billboardRef} position={[0, 2.25, 0]}>
        {/* Background plate */}
        <mesh position={[0, 0, -0.01]}>
          <planeGeometry args={[1.6, 0.42]} />
          <meshBasicMaterial color="#090d16" transparent opacity={0.82} />
        </mesh>

        {/* Outer team colored border */}
        <lineSegments>
          <edgesGeometry args={[new THREE.PlaneGeometry(1.6, 0.42)]} />
          <lineBasicMaterial color={teamColors.accent} />
        </lineSegments>

        {/* Health Bar Background */}
        <mesh position={[0, -0.06, 0]}>
          <planeGeometry args={[1.4, 0.09]} />
          <meshBasicMaterial color="#1f2937" />
        </mesh>
        {/* Health Bar Current Fill (Green -> Yellow -> Red) */}
        <mesh
          position={[-0.7 + (1.4 * healthPercent) / 2, -0.06, 0.005]}
          scale={[healthPercent, 1, 1]}
        >
          <planeGeometry args={[1.4, 0.09]} />
          <meshBasicMaterial
            color={
              healthPercent > 0.5 ? '#10b981' : healthPercent > 0.25 ? '#f59e0b' : '#ef4444'
            }
