      </group>

      {/* ================================================================== */}
      {/* 2. LEGS & LOWER BODY                                               */}
      {/* ================================================================== */}
      {/* Left Leg */}
      <group ref={leftLegRef} position={[-0.2, 0.65, 0]}>
        {/* Thigh */}
        <mesh position={[0, -0.2, 0]} castShadow>
