    isAiming,
    isSprinting,
    isFiring,
    position,
    rotation,
    loadout,
    players,
    playerId,
    killfeed,
    hitmarkers,
    damageIndicators,
    recoilOffset,
    activeFps,
    ping,
    matchState,
    graphicsSettings,
    pruneKillfeed,
    pruneHitmarkers,
    pruneDamageIndicators,
  } = useGameStore();

  // Periodic pruning of transient UI feedback
  useEffect(() => {
    const interval = setInterval(() => {
      pruneKillfeed();
      pruneHitmarkers();
      pruneDamageIndicators();
    }, 100);
    return () => clearInterval(interval);
  }, [pruneKillfeed, pruneHitmarkers, pruneDamageIndicators]);

  const currentWeapon = WEAPON_CONFIGS[currentWeaponId];
  const isSniperADS = isAiming && currentWeaponId === 'SR-99';

