                  </thead>
                  <tbody>
                    {bravoPlayers.length > 0 ? (
                      bravoPlayers.map((p) => renderPlayerRow(p, false))
                    ) : (
                      <tr>
                        <td colSpan={9} className="py-4 text-center text-xs text-gray-500">
                          No operators in Bravo Team
